include "smokeunit.lua"

local rad = math.rad
local COB2RAD = math.pi / 32768
local SIG_AIM = 1
local gun_index = 0

local COB_PIECE = {[0] = flare1, [1] = flare2}

local function Blow(list, flags)
	for _, p in ipairs(list) do Explode(p, flags) end
end

function script.Create()
	gun_index = 0
	StartThread(SmokeUnit, {base})
end

function script.SweetSpot()
	return base
end

function script.AimFromWeapon(num)
	return turret2
end

function script.QueryWeapon(num)
	return COB_PIECE[gun_index]
end

function script.AimWeapon(num, heading, pitch)
	Signal(SIG_AIM)
	SetSignalMask(SIG_AIM)
	Turn(turret1, y_axis, heading, rad(150))
	Turn(turret2, x_axis, -pitch, rad(150))
	WaitForTurn(turret1, y_axis)
	WaitForTurn(turret2, x_axis)
	return true
end

function script.FireWeapon(num)
	if gun_index == 0 then
		Move(barrel1, z_axis, -7.5)
		Sleep(150)
		Move(barrel1, z_axis, 0, 7.5)
	end
	if gun_index == 1 then
		Move(barrel2, z_axis, -7.5)
		Sleep(150)
		Move(barrel2, z_axis, 0, 7.5)
	end
	gun_index = gun_index == 0 and 1 or 0
end

function script.RockUnit(x, z)
